CREATE COLUMN TABLE "TEST_AP"."OKPI" ("AbsEntry" INTEGER CS_INT NOT NULL , "Code" NVARCHAR(250), "Name" NVARCHAR(250) NOT NULL , "Desc" NVARCHAR(254), "ValueType" NVARCHAR(200), "ValueQid" INTEGER CS_INT, "ViewName" NVARCHAR(250), "ViewCtg" NVARCHAR(250), "ViewSyn" NVARCHAR(250), "TrendType" NVARCHAR(250), "TrendQid" INTEGER CS_INT, "GoalValue" DECIMAL(21,6) CS_FIXED, "GoalQid" NVARCHAR(11), "GoalDesc" NVARCHAR(250), "CalcFrml" NVARCHAR(250), "Visible" NVARCHAR(1) DEFAULT 'Y', "SBetter" NVARCHAR(1) DEFAULT 'Y', "Author" NVARCHAR(32), "Version" NVARCHAR(13), "CreateDate" LONGDATE CS_LONGDATE, "CreateTime" SMALLINT CS_INT, "IsSystem" NVARCHAR(1) DEFAULT 'N', "MeasUnit" NVARCHAR(50) DEFAULT '0', "RevSign" NVARCHAR(1) DEFAULT 'N', "Unit" NVARCHAR(250), PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OKPI_NAME" ON "TEST_AP"."OKPI" ( "Name" ASC )